psql -v ON_ERROR_STOP=1 <<'SQL'
CREATE TABLE IF NOT EXISTS orders(id bigserial PRIMARY KEY, item text, amount numeric, created_at timestamptz DEFAULT now());
INSERT INTO orders(item,amount) SELECT 'item-'||floor(random()*200), round((random()*1000)::numeric,2) FROM generate_series(1, 20+floor(random()*40)::int);
SELECT count(*) AS total, round(avg(amount),2) AS avg_amount FROM orders;
SELECT item, count(*) FROM orders GROUP BY item ORDER BY 2 DESC LIMIT 5;
DELETE FROM orders WHERE created_at < now() - interval '7 days';
SQL
echo "postgres load done"

